``` {.python .cell-code}
import sys; sys.path.insert(0, "../../theme")
import leaptheme  # house style: colours, fonts, hover crosshairs — automatic
import pandas as pd
import plotly.express as px

years = list(range(3001, 3022))
data = []
for region, base, trend, shock_year, shock in [
    ("Lothlórien",  84, 0.5, 3018, -30),
    ("Rivendell",   41, 0.3, 3018, -12),
    ("Mirkwood",    23, -0.8, 3010, -6),
    ("Grey Havens", 12, 0.9, None, 0),
]:
    level = base
    for y in years:
        level += trend
        if shock_year and y >= shock_year:
            level += shock / 3
        data.append({"year": y, "region": region,
                     "output": round(max(level, 1), 1)})

df = pd.DataFrame(data)

fig = px.line(
    df, x="year", y="output", color="region",
    labels={"year": "Third Age year", "output": "Output ('000 cakes)",
            "region": "Region"},
)
leaptheme.watermark(
    fig,
    article="Supply Chains of Middle-earth",
    citation="Gamgee (2026)",
)
fig.show()
```

